def solve(inputs: dict) -> float:
    """
    Compute M^n mod p where M is a 2x2 matrix.
    inputs should contain 'matrix', 'exponent', and 'modulus'.
    """
    matrix = inputs['matrix']
    exponent = inputs['exponent']
    modulus = inputs['modulus']

    def matrix_mult(A, B, mod):
        """Multiply two 2x2 matrices modulo mod"""
        result = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    def matrix_pow(M, n, mod):
        """Compute M^n mod p using fast exponentiation"""
        if n == 0:
            return [[1, 0], [0, 1]]  # Identity matrix
        if n == 1:
            return [[M[i][j] % mod for j in range(2)] for i in range(2)]

        # Start with identity
        result = [[1, 0], [0, 1]]
        base = [[M[i][j] % mod for j in range(2)] for i in range(2)]

        while n > 0:
            if n % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            n //= 2

        return result

    M_pow = matrix_pow(matrix, exponent, modulus)

    # Sum all entries
    total = sum(M_pow[i][j] for i in range(2) for j in range(2))
    return float(total % modulus)

