def solve(inputs: dict) -> float:
    """
    Compute the numerator of a continued fraction convergent.
    inputs should contain 'terms' which is a list of continued fraction terms.
    Uses the recurrence: p_n = a_n * p_{n-1} + p_{n-2}
    """
    terms = inputs['terms']

    if len(terms) == 0:
        return 0.0
    if len(terms) == 1:
        return float(terms[0])

    # Initialize p_prev and p
    p_prev = 1  # p_{-1}
    p = terms[0]  # p_0

    # Apply recurrence for remaining terms
    for i in range(1, len(terms)):
        a = terms[i]
        p_new = a * p + p_prev
        p_prev = p
        p = p_new

    return float(p)

